const input = $json.body ?? $json;
const eventType = String(input.event_type ?? input.type ?? input.status ?? '').toLowerCase();
const dispatchId = input.dispatch_id ?? input.message_id ?? input.provider_message_id ?? null;
const dealId = input.deal_id ?? null;
const leadId = input.lead_id ?? null;
const propertyId = input.property_id ?? null;
const channel = String(input.channel ?? '').toLowerCase();
const deliveryStatus = String(input.delivery_status ?? input.status ?? '').toLowerCase();
const inboundMessage = input.message ?? input.body ?? input.text ?? null;
const identityOk = Boolean(dispatchId && leadId);
const responseReceived = Boolean(inboundMessage && String(inboundMessage).trim());
const delivered = ['delivered','delivery_confirmed','sent','accepted'].includes(deliveryStatus) || ['delivered','message.delivered','delivery'].includes(eventType);
const failed = ['failed','undelivered','bounced','rejected'].includes(deliveryStatus) || ['failed','message.failed','bounce'].includes(eventType);
const receiptPending = !delivered && !failed && !responseReceived;
let status = 'receipt_pending';
let action = 'await_receipt';
let nextWorkflow = 'WF-265';

if (!identityOk) {
  status = 'invalid_callback';
  action = 'human_review';
  nextWorkflow = 'WF-126';
} else if (responseReceived) {
  status = 'response_received';
  action = 'classify_seller_response';
  nextWorkflow = 'WF-265';
} else if (failed) {
  status = 'delivery_failed';
  action = 'retry_or_alternate_channel';
  nextWorkflow = 'WF-263';
} else if (delivered) {
  status = 'delivered_awaiting_response';
  action = 'await_seller_response';
  nextWorkflow = 'WF-265';
} else if (receiptPending) {
  status = 'receipt_pending';
  action = 'await_receipt';
  nextWorkflow = 'WF-265';
}

return [{ json: {
  ...input,
  workflow_id: 'WF-264',
  workflow_name: 'Delivery Receipt / Provider Callback → Seller Response Controller',
  status,
  action,
  next_workflow: nextWorkflow,
  dispatch_id: dispatchId,
  provider_event: {
    event_type: eventType || null,
    delivery_status: deliveryStatus || null,
    channel: channel || null,
    provider_message_id: input.provider_message_id ?? input.message_id ?? null
  },
  seller_response: responseReceived ? {
    received: true,
    message: String(inboundMessage).trim(),
    received_at: input.received_at ?? new Date().toISOString()
  } : { received: false },
  delivery: {
    delivered,
    failed,
    receipt_pending: receiptPending
  },
  identity_valid: identityOk,
  human_review_required: status === 'invalid_callback',
  crm_activity: {
    activity_type: responseReceived ? 'seller_response_received' : 'communication_delivery_update',
    workflow_id: 'WF-264',
    status,
    action,
    dispatch_id: dispatchId,
    next_workflow: nextWorkflow
  }
} }];
